function parseHotText(text) {
  if (text == null) return null;
  const str = String(text);
  const matched = /([\d.]+)\s*(亿|万|w|W)?/.exec(str);
  if (!matched) return null;
  let value = Number.parseFloat(matched[1]);
  if (!Number.isFinite(value)) return null;
  const unit = matched[2];
  if (unit === "\u4EBF") value *= 1e8;
  else if (unit === "\u4E07" || unit === "w" || unit === "W") value *= 1e4;
  return Math.round(value);
}
function formatHot2(value) {
  if (value == null || !Number.isFinite(value) || value <= 0) return "";
  if (value >= 1e8) return `${Math.round(value / 1e7) / 10}\u4EBF`;
  if (value >= 1e4) return `${Math.round(value / 1e3) / 10}\u4E07`;
  return String(value);
}
function normalizeScore(hot, index, poolSize, maxHot, weight) {
  const hotPart = maxHot > 0 && hot ? hot / maxHot : 1 - index / poolSize * 0.5;
  const rankPart = 1 - index / poolSize * 0.5;
  return (hotPart * 0.75 + rankPart * 0.25) * weight;
}
function estimatePlatformHot(rank, total = 30, weight = 0.83, title = "") {
  const r = Math.max(1, rank);
  const n = Math.max(total, 10);
  const t = Math.min(1, Math.max(0, (r - 1) / (n - 1)));
  const peakHot = 108e5 * Math.max(0.75, Math.min(1.2, weight || 0.85));
  const minHot = 45e4;
  const decay = Math.exp(-2.25 * Math.pow(t, 0.82));
  const baseValue = minHot + (peakHot - minHot) * decay;
  const nextT = Math.min(1, r / (n - 1));
  const nextBase = minHot + (peakHot - minHot) * Math.exp(-2.25 * Math.pow(nextT, 0.82));
  const gap = Math.max(12e3, baseValue - nextBase);
  let hash = 0;
  for (let i = 0; i < (title || "").length; i++) {
    hash = (hash << 5) - hash + title.charCodeAt(i);
    hash |= 0;
  }
  const seed = Math.abs(hash || r * 31);
  const jitterRatio = (seed % 1e3 / 1e3 - 0.5) * 0.36;
  const jitter = gap * jitterRatio;
  return Math.round(baseValue + jitter);
}
function clampInt(raw, fallback, min, max) {
  const n = Number.parseInt(raw || "", 10);
  if (!Number.isFinite(n)) return fallback;
  return Math.min(max, Math.max(min, n));
}
function isCommonAggregateArgs(limit, per, only) {
  return (limit === 20 || limit === 30) && per === DEFAULT_PER_SOURCE && !only.length;
}
