init_common();
init_fetch_upstream();
var ServiceHuxiu = class {
  // 缓存成功结果：虎嗅官方 API 有阿里云 WAF 防护，降低请求频率
  #cache = null;
  handle() {
    return async (ctx) => {
      const data2 = await this.#fetch();
      renderByEncoding(ctx, {
        text: () => `\u864E\u55C5\u70ED\u699C

${data2.map((e, i) => `${i + 1}. ${e.title}
   \u70ED\u5EA6 ${e.hot} \xB7 ${e.link}`).join("\n\n")}`,
        markdown: () => `# \u864E\u55C5\u70ED\u699C

${data2.slice(0, 20).map(
          (e, i) => `### ${i + 1}. [${e.title}](${e.link})

${e.cover ? `![${e.title}](${e.cover})

` : ""}\u{1F525} ${e.hot}

---
`
        ).join("\n")}`,
        json: () => Common.buildJson(data2)
      });
    };
  }
  async #fetch() {
    const FRESH_TTL = 10 * 60 * 1e3;
    const STALE_TTL = 2 * 60 * 60 * 1e3;
    if (this.#cache && Date.now() - this.#cache.ts < FRESH_TTL) {
      return this.#cache.data;
    }
    const data2 = await this.#fetchOfficial() ?? await this.#fetchTophub();
    if (data2) {
      this.#cache = { data: data2, ts: Date.now() };
      return data2;
    }
    if (this.#cache && Date.now() - this.#cache.ts < STALE_TTL) {
      return this.#cache.data;
    }
    throw new Error("\u864E\u55C5\u70ED\u699C\u83B7\u53D6\u5931\u8D25\uFF08\u5B98\u65B9\u63A5\u53E3\u88AB WAF \u62E6\u622A\u4E14\u805A\u5408\u6E90\u4E0D\u53EF\u7528\uFF09\uFF0C\u8BF7\u7A0D\u540E\u91CD\u8BD5");
  }
  // 虎嗅官方 API（阿里云 WAF 对部分出口 IP 弹滑块验证，可能失败）
  async #fetchOfficial() {
    try {
      const response = await fetchUpstream("https://api.huxiu.com/v1/article/hotList", {
        headers: {
          Accept: "application/json, text/plain, */*",
          Referer: "https://www.huxiu.com/"
        },
        timeoutMs: 8e3,
        retry: 0
      });
      const contentType = response.headers.get("content-type") || "";
      if (contentType.includes("text/html")) return null;
      if (!response.ok) return null;
      const apiData = await response.json();
      if (apiData.code !== 1 || !Array.isArray(apiData.data)) return null;
      return apiData.data.map((v, idx) => ({
        rank: idx + 1,
        title: v.title,
        desc: v.summary || "",
        cover: v.pic || "",
        author: v.user_info?.username || "",
        hot: v.score ?? 0,
        comments: v.comment_count ?? 0,
        timestamp: v.dateline,
        link: `https://www.huxiu.com/article/${v.aid}.html`
      }));
    } catch {
      return null;
    }
  }
  // 降级源：tophub.today 聚合的虎嗅网热文
  async #fetchTophub() {
    try {
      const response = await fetchUpstream("https://tophub.today/n/5VaobgvAj1", {
        headers: {
          Referer: "https://tophub.today/c/tech"
        },
        timeoutMs: 1e4,
        retry: 0
      });
      if (!response.ok) return null;
      const html = await response.text();
      const rowRe = /<td align="center">(\d+)\.<\/td>\s*<td class="al" align="center"><img src="([^"]+)"[\s\S]*?<td class="al">\s*<div><a href="([^"]+)"[^>]*>([^<]+)<\/a><\/div>\s*<div class="item-desc">([^<]*)<\/div>/g;
      const items = [];
      let m;
      while ((m = rowRe.exec(html)) !== null) {
        items.push({
          rank: Number(m[1]),
          title: m[4].trim(),
          desc: "",
          cover: m[2],
          author: "",
          hot: m[5].trim(),
          comments: 0,
          timestamp: 0,
          link: m[3]
        });
      }
      return items.length > 0 ? items : null;
    } catch {
      return null;
    }
  }
};
var serviceHuxiu = new ServiceHuxiu();

