var RSS_URL = "https://www.nodeseek.com/rss.xml";
var CATEGORY_MAP = {
  tech: "\u6280\u672F",
  daily: "\u65E5\u5E38",
  trade: "\u4EA4\u6613",
  info: "\u8D44\u8BAF",
  review: "\u8BC4\u6D4B",
  dev: "\u5F00\u53D1",
  carpool: "\u62FC\u8F66",
  "photo-share": "\u6652\u56FE",
  expose: "\u66DD\u5149"
};
var ServiceNodeSeek = class {
  handle() {
    return async (ctx) => {
      const data2 = await cached("nodeseek", () => this.#fetch());
      renderByEncoding(ctx, {
        text: () => `NodeSeek \u70ED\u5E16

${data2.map((e) => `${e.rank}. ${e.title} [${e.category_label}] @${e.author}`).join("\n")}`,
        markdown: () => `# \u{1F310} NodeSeek \u70ED\u5E16

${data2.map(
          (e) => `### ${e.rank}. [${e.title}](${e.link})

\`${e.category_label}\` \xB7 @${e.author} \xB7 ${e.created}

${e.description ? `${e.description}

` : ""}---
`
        ).join("\n")}`,
        json: () => Common.buildJson(data2)
      });
    };
  }
  async #fetch() {
    const response = await fetchUpstream(RSS_URL, {
      headers: {
        Accept: "application/rss+xml, application/xml, text/xml"
      },
      timeoutMs: 1e4
    });
    if (!response.ok) {
      throw new Error(`NodeSeek RSS \u8BF7\u6C42\u5931\u8D25: HTTP ${response.status}`);
    }
    const xml = await response.text();
    const items = [];
    const itemRegex = /<item>([\s\S]*?)<\/item>/gi;
    let match;
    while ((match = itemRegex.exec(xml)) !== null) {
      const block = match[1];
      const title = this.#extractCDATA(block, "title") || "";
      const link = this.#extractRaw(block, "link") || "";
      const category = this.#extractCDATA(block, "category") || "";
      const author = this.#extractCDATA(block, "dc:creator") || "";
      const description = this.#extractCDATA(block, "description") || "";
      const pubDate = this.#extractRaw(block, "pubDate") || "";
      const created_at = pubDate ? Date.parse(pubDate) : Date.now();
      const created = dayjs(created_at).format("YYYY-MM-DD HH:mm:ss");
      items.push({
        rank: items.length + 1,
        title,
        link,
        category,
        category_label: CATEGORY_MAP[category] || category,
        author,
        description,
        created,
        created_at
      });
    }
    return items;
  }
  // 提取 <tag><![CDATA[value]]></tag> 中的 value
  #extractCDATA(block, tag) {
    const re = new RegExp(`<${tag}><!\\[CDATA\\[([\\s\\S]*?)\\]\\]></${tag}>`, "i");
    return re.exec(block)?.[1]?.trim() || "";
  }
  // 提取 <tag>value</tag> 中的 value
  #extractRaw(block, tag) {
    const re = new RegExp(`<${tag}>([^<]*)</${tag}>`, "i");
    return re.exec(block)?.[1]?.trim() || "";
  }
};
var serviceNodeSeek = new ServiceNodeSeek();

