// src/modules/reddit.module.ts
init_common();
init_fetch_upstream();
var ServiceReddit = class {
  // 缓存成功结果：Reddit 对未认证请求限流严格（约 1 分钟窗口仅 2~3 次，429 后需等待约 1 分钟）
  #cache = null;
  handle() {
    return async (ctx) => {
      const data2 = await this.#fetch();
      renderByEncoding(ctx, {
        text: () => `Reddit \u70ED\u5E16 (r/all)

${data2.map((e, i) => `${i + 1}. ${e.title}
   r/${e.subreddit} \xB7 ${e.author} \xB7 ${e.link}`).join("\n\n")}`,
        markdown: () => `# Reddit \u70ED\u5E16 (r/all)

${data2.slice(0, 25).map((e, i) => `### ${i + 1}. [${e.title}](${e.link})

r/${e.subreddit} \xB7 ${e.author}

---
`).join("\n")}`,
        json: () => Common.buildJson(data2)
      });
    };
  }
  async #fetch() {
    const FRESH_TTL = 5 * 60 * 1e3;
    const STALE_TTL = 60 * 60 * 1e3;
    if (this.#cache && Date.now() - this.#cache.ts < FRESH_TTL) {
      return this.#cache.data;
    }
    let lastError = null;
    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        const response = await fetchUpstream("https://www.reddit.com/r/all/hot.rss", {
          headers: {
            "User-Agent": "cloudflare:daily-hot:0.1.0 (by /u/dailyhot)",
            Accept: "application/atom+xml"
          },
          timeoutMs: 1e4,
          retry: 0
        });
        if (response.ok) {
          const xml = await response.text();
          const data2 = this.#parse(xml);
          this.#cache = { data: data2, ts: Date.now() };
          return data2;
        }
        if (response.status === 429 && attempt < 2) {
          const retryAfter = Number(response.headers.get("retry-after"));
          const delay = Number.isFinite(retryAfter) && retryAfter > 0 && retryAfter <= 5 ? retryAfter * 1e3 : 2e3 * (attempt + 1);
          await new Promise((r) => setTimeout(r, delay));
          continue;
        }
        throw new Error(`Failed to fetch reddit: HTTP ${response.status}`);
      } catch (e) {
        lastError = e;
        if (attempt < 2) await new Promise((r) => setTimeout(r, 1e3));
      }
    }
    if (this.#cache && Date.now() - this.#cache.ts < STALE_TTL) {
      return this.#cache.data;
    }
    throw lastError instanceof Error ? lastError : new Error("Failed to fetch reddit");
  }
  #parse(xml) {
    const items = [];
    const entryRe = /<entry>([\s\S]*?)<\/entry>/g;
    let m;
    let rank = 1;
    while ((m = entryRe.exec(xml)) !== null) {
      const e = m[1];
      const title = (e.match(/<title>([\s\S]*?)<\/title>/) || [])[1]?.trim() || "";
      const link = (e.match(/<link[^>]*href="([^"]+)"/) || [])[1] || "";
      const subreddit = (e.match(/<category term="([^"]+)"/) || [])[1] || "";
      const authorRaw = (e.match(/<name>([\s\S]*?)<\/name>/) || [])[1]?.trim() || "";
      const author = authorRaw.replace(/^\/u\//, "");
      let thumbnail = (e.match(/media:thumbnail[^>]*url="([^"]+)"/) || [])[1] || "";
      if (!thumbnail) {
        const ct = (e.match(/<content type="html">([\s\S]*?)<\/content>/) || [])[1] || "";
        const unescaped = ct.replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&amp;amp;/g, "&").replace(/&amp;/g, "&");
        thumbnail = (unescaped.match(/<img src="([^"]+)"/) || [])[1] || "";
      }
      if (title && link) {
        items.push({ rank: rank++, title, link, subreddit, author, thumbnail });
      }
    }
    return items;
  }
};
var serviceReddit = new ServiceReddit();

